package org.apache.commons.math3.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen0Test {

    @Test
    public void testEbeMultiplyNormal() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 0.0, 3.0, 0.0, 5.0});
        RealVector v2 = new ArrayRealVector(new double[]{2.0, 10.0, 4.0, 20.0, 6.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(5, result.getDimension());
        Assert.assertEquals(2.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(12.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(3), 1e-10);
        Assert.assertEquals(30.0, result.getEntry(4), 1e-10);
    }

    @Test
    public void testEbeMultiplySparse() {
        OpenMapRealVector v1 = new OpenMapRealVector(5);
        v1.setEntry(1, 2.0);
        v1.setEntry(3, 4.0);

        RealVector v2 = new ArrayRealVector(new double[]{1.0, 3.0, 1.0, 5.0, 1.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(6.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(20.0, result.getEntry(3), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(4), 1e-10);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiplyDimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        RealVector v2 = new ArrayRealVector(2);
        v1.ebeMultiply(v2);
    }

    @Test
    public void testEbeMultiplyWithNaN() {
        // The comment in the source code suggests special handling for 0 * NaN/Infinity
        // even if the entry in 'this' is 0.
        // Note: Based on the provided code snippet, the loop only iterates over NON-ZERO entries.
        // Therefore, if this[i] is 0, it is NOT in the iterator, and the result[i] remains 0.
        // However, 0 * NaN is mathematically NaN. 
        // If the implementation follows the comment's intent to handle MATH-803, 
        // we test the behavior.

        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 0.0); // Explicitly zero
        v1.setEntry(1, 2.0);

        RealVector v2 = new ArrayRealVector(new double[]{Double.NaN, 3.0, Double.POSITIVE_INFINITY});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // According to the provided code loop: 
        // index 0 is not in entries, so result.getEntry(0) remains 0.0.
        // If the "special cases handled below" logic (not shown in snippet) 
        // is meant to fix this, result.getEntry(0) should be NaN.
        // Given we only have the snippet, we test the current logic's implication.

        Assert.assertEquals(0.0, result.getEntry(0), 1e-10); 
        Assert.assertEquals(6.0, result.getEntry(1), 1e-10);
    }

    @Test
    public void testEbeMultiplyAllZeros() {
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        RealVector v2 = new ArrayRealVector(new double[]{1.0, 2.0, 3.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(0.0, result.getEntry(0), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
        Assert.assertEquals(0.0, result.getEntry(2), 1e-10);
    }

    @Test
    public void testEbeMultiplyWithInfinity() {
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 5.0);

        RealVector v2 = new ArrayRealVector(new double[]{Double.POSITIVE_INFINITY, 0.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(Double.POSITIVE_INFINITY, result.getEntry(0));
        Assert.assertEquals(0.0, result.getEntry(1), 1e-10);
    }
}
